import { describe, it, expect } from 'vitest';
import { ToolRegistry } from './registry.js';

describe('ToolRegistry', () => {
  it('rejects input missing a required property with a ToolResponse and never calls the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor])', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: { location: { type: 'string' } },
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect(executorCalls).toBe(0);
    expect(response).toEqual({ result: expect.stringContaining('location') });
    expect(response.result).toMatch(/required/i);
  });
});
